def _handle_device_inbox_job_get(
        self, device_id: str, job_id: str) -> None:
    # The job detail query takes no request body and no query
    # parameters: either one is a 400 (field request_body / query).
    # The two path identifiers are already strictly percent-decoded as
    # UTF-8 by the router (a bad escape is 400 with the offending
    # segment). keep_blank_values so a bare ``?foo`` flag is an actual
    # (unknown) parameter rather than being silently dropped, while a
    # trailing ``?`` with no parameter at all is accepted.
    query = parse_qs(urlsplit(self.path).query,
                     keep_blank_values=True)
    if query:
        self._send_json(400, {"message": "query parameters are not "
                                         "accepted",
                              "field": "query"})
        return
    try:
        length = int(self.headers.get("Content-Length", "0"))
    except ValueError:
        self._send_json(400, {"message": "invalid Content-Length header",
                              "field": "Content-Length"})
        return
    if length > 0:
        # Drain the body so the connection stays usable, then reject.
        self.rfile.read(length)
        self._send_json(400, {"message": "request body must be empty",
                              "field": "request_body"})
        return
    try:
        body = self.service.inbox_job_get(device_id, job_id)
    except ServiceError as error:
        self._send_json(error.status_code, error.to_body())
        return
    self._send_json(200, body)

def _sync_query_params(self) -> Optional[Tuple[str, Optional[int], int]]:
    """Validate the sync GET params: single ``device_id``, optional
    non-negative ``after`` (omitted -> the stored cursor), and ``limit``
    in 1..100 (default 100). Returns ``None`` after sending a 400."""
    query = parse_qs(urlsplit(self.path).query)

    device_ids = query.get("device_id", [])
    if len(device_ids) != 1 or not device_ids[0]:
        self._send_json(400, {"message": "device_id is required",
                              "field": "device_id"})
        return None

    after_values = query.get("after")
    if after_values is None:
        after: Optional[int] = None
    elif len(after_values) != 1:
        self._send_json(400, {"message": "after must appear at most once",
                              "field": "after"})
        return None
    else:
        try:
            after = int(after_values[0])
        except ValueError:
            self._send_json(400, {"message": "after must be an integer",
                                  "field": "after"})
            return None
        if after < 0:
            self._send_json(400, {"message": "after is out of range",
                                  "field": "after"})
            return None

    limit = self._int_param(query, "limit", default=100,
                            minimum=1, maximum=100)
    if limit is None:
        return None
    return device_ids[0], after, limit

